update public.exercise_questions set question_text='Em uma situação de sala de aula, o professor acompanha como os estudantes estão compreendendo um conteúdo e usa essas evidências para ajustar as próximas intervenções. Nesse caso, a avaliação formativa se caracteriza por', feedback_hint='A avaliação formativa acompanha o processo e produz informações que podem orientar intervenções pedagógicas antes do encerramento da aprendizagem.', updated_at=now() where id='46357d48-4d2a-4fb8-a879-0c936cbe58f4'; update public.exercise_questions set question_text='Ao ensinar o sistema de escrita alfabética, é necessário compreender a relação entre unidades da fala e unidades da escrita. Nesse contexto, o princípio alfabético se caracteriza por', feedback_hint='O princípio alfabético envolve compreender relações sistemáticas entre unidades sonoras e suas representações na escrita, sem reduzir escrita e fala a equivalentes perfeitos.', updated_at=now() where id='036a4da6-b021-430f-aa4d-82e86280a2e1'; update public.exercise_questions set question_text='Em uma atividade de leitura, um estudante consegue reconhecer palavras com maior rapidez, mas ainda apresenta dificuldades para construir sentidos a partir do texto. Essa situação mostra que fluência e compreensão', feedback_hint='Fluência envolve maior automaticidade e precisão na leitura; compreensão envolve construir e interpretar sentidos. Elas se relacionam, mas não são equivalentes.', updated_at=now() where id='f244d365-6695-46ec-acc7-7e4ee4513220'; update public.exercise_questions set question_text='Durante uma atividade de alfabetização, o professor pede que os estudantes observem sons da fala e sua representação escrita. Para interpretar corretamente a situação, é importante reconhecer que grafema e fonema não são sinônimos porque', feedback_hint='Fonema se refere a uma unidade sonora distintiva; grafema é uma representação escrita. A relação entre eles é sistemática, mas os conceitos pertencem a planos diferentes.', updated_at=now() where id='ec5fa354-a1d6-417c-b875-63a974ff3531';
